package net.officefloor.hq.app.setting;

import java.util.Arrays;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * A sheet's permission matrix: for each action set, the roles allowed it, as typed and shown (comma separated role
 * labels). An action not set keeps the standing rule: open, settle, void and close by clerk and steward; reassign and
 * reopen by steward. Not dated.
 */
public record Permissions(Map<String, String> set) {

    public static final String OPEN = "open";
    public static final String SETTLE = "settle";
    public static final String VOID = "void";
    public static final String REASSIGN = "reassign";
    public static final String CLOSE = "close";
    public static final String REOPEN = "reopen";

    /** The actions the matrix covers, in the order they are shown and recorded. */
    public static final List<String> ACTIONS = List.of(OPEN, SETTLE, VOID, REASSIGN, CLOSE, REOPEN);

    /** The setting key of an action's entry: perm-&lt;action&gt;. */
    public static String key(String action) {
        return "perm-" + action;
    }

    /** The roles allowed the action when none are set. */
    private static Set<Role> standing(String action) {
        return switch (action) {
            case REASSIGN, REOPEN -> EnumSet.of(Role.STEWARD);
            default -> EnumSet.of(Role.CLERK, Role.STEWARD);
        };
    }

    /** The roles in a comma separated list as typed (each case and outer spaces ignored), or null when one is not a role a
     * permission can name (clerk or steward). */
    public static Set<Role> parse(String roles) {
        Set<Role> parsed = EnumSet.noneOf(Role.class);
        for (String label : roles.split(",", -1)) {
            Role role = Role.of(label);
            if (role == null || role == Role.VIEWER) {
                return null;
            }
            parsed.add(role);
        }
        return parsed;
    }

    /** The roles as shown: their labels, comma separated, in the order typed without repeats. */
    public static String label(String roles) {
        return Arrays.stream(roles.split(",", -1)).map(Role::of).map(Role::label).distinct()
                .collect(Collectors.joining(","));
    }

    /** Whether the role may take the action. */
    public boolean allows(String action, Role role) {
        String roles = set.get(action);
        return (roles == null ? standing(action) : parse(roles)).contains(role);
    }

    /** Each action's entry as shown, by action ("": blank, the standing rule). */
    public Map<String, String> entries() {
        Map<String, String> entries = new LinkedHashMap<>();
        ACTIONS.forEach((a) -> entries.put(a, set.getOrDefault(a, "")));
        return entries;
    }
}
package net.officefloor.hq.app.setting;

/**
 * A user's role on a sheet: a clerk (any name not given another role) settles only within the clerk limit; a steward
 * settles anything; a viewer sees everything and changes nothing.
 */
public enum Role {
    CLERK, STEWARD, VIEWER;

    /** The role as it is typed and shown: lower case. */
    public String label() {
        return name().toLowerCase();
    }

    /** The role with this label (case and outer spaces ignored), or null. */
    public static Role of(String label) {
        String wanted = label == null ? "" : label.trim();
        for (Role role : values()) {
            if (role.label().equalsIgnoreCase(wanted)) {
                return role;
            }
        }
        return null;
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.sql.Date;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Rounding;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SettingRepository {

    /** The floor a sheet starts with. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms a sheet starts with, in days. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent a sheet starts with. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    private final JdbcTemplate jdbc;

    public SettingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's settings: the dated ones in force on its today (and every value recorded), its policy date, its period numbering from date and its roles, by user name. */
    public Settings find(String sheetId) {
        List<UserRole> roles = jdbc.query("SELECT sheet_id, user_name, role FROM user_role WHERE sheet_id = ?"
                + " ORDER BY user_name", (rs, n) -> new UserRole(rs.getString("sheet_id"), rs.getString("user_name"),
                        Role.valueOf(rs.getString("role"))), sheetId);
        List<Date> found = jdbc.query("SELECT today FROM sheet WHERE id = ?", (rs, n) -> rs.getDate("today"), sheetId);
        LocalDate today = found.isEmpty() || found.get(0) == null ? LocalDate.now() : found.get(0).toLocalDate();
        List<Person> people = new ArrayList<>();
        for (Person p : found) {
            List<GradeFrom> own = grades.getOrDefault(p.id(), List.of(new GradeFrom(p.grade(), null)));
            people.add(new Person(p.id(), p.sheetId(), p.name(), Person.gradeOn(own, on, p.grade()), p.version(),
                    p.statementCount(), p.statedTotal(), p.statementDate(), p.retiredFrom(),
                    List.copyOf(holds.getOrDefault(p.id(), List.of())), List.copyOf(own), p.terms()));
        }
        return people;
    }

    /**
     * Record a statement just taken of the person: one more statement, with its due-total and date; the
     * person as stored. Not an edit, so it leaves the version alone.
     */
    public Person recordStatement(Person person, String statedTotal, LocalDate date) {
        jdbc.update("UPDATE person SET statement_count = statement_count + 1, stated_total = ?, statement_date = ?"
                + " WHERE id = ? AND sheet_id = ?", statedTotal, Date.valueOf(date), person.id(), person.sheetId());
        return find(person.sheetId(), person.id());
    }

    /** Retire the person from this date; the person as stored. Not an edit, so it leaves the version alone. */
    public Person retire(Person person, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE id = ? AND sheet_id = ?", Date.valueOf(from), person.id(),
                person.sheetId());
        return find(person.sheetId(), person.id());
    }

    /** Add a hold to the person; the person as stored. Not an edit, so it leaves the version alone. */
    public Person hold(Person person, Hold hold) {
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
                person.sheetId(), person.id(), hold.from() == null ? null : Date.valueOf(hold.from()),
                hold.to() == null ? null : Date.valueOf(hold.to()));
        return find(person.sheetId(), person.id());
    }

    private static Person map(ResultSet rs, int n) throws SQLException {
        return new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"), rs.getString("grade"),
                rs.getInt("version"), rs.getInt("statement_count"), rs.getString("stated_total"),
                rs.getObject("statement_date", LocalDate.class),
                rs.getObject("retired_from", LocalDate.class), List.of()).withTerms(rs.getObject("terms", Integer.class));
    }
}
